export enum TechnicalDepth {
  HOBBYIST = 'Hobbyist',
  ENGINEER = 'Software Engineer',
  RESEARCHER = 'ML Researcher',
  EXECUTIVE = 'Strategic Executive'
}

export interface TechnicalProfile {
  depth: TechnicalDepth;
  focusAreas: string[];
  digestInterval: '4h' | '12h' | '24h';
  notificationEnabled: boolean;
}

export interface GroundingSource {
  title: string;
  uri: string;
}

export interface DigestItem {
  id: string;
  timestamp: number;
  title: string;
  summary: string;
  keyTakeaways: string[];
  technicalAnalysis: string;
  sources: GroundingSource[];
  impactScore: number; // 1-10
}

export interface PipelineState {
  isProcessing: boolean;
  lastRun: number | null;
  history: DigestItem[];
  profile: TechnicalProfile;
}

import { TechnicalDepth, TechnicalProfile } from './types';

export const DEFAULT_PROFILE: TechnicalProfile = {
  depth: TechnicalDepth.ENGINEER,
  focusAreas: ['LLM Architectures', 'Edge AI', 'RAG Optimizations'],
  digestInterval: '24h',
  notificationEnabled: true,
};

export const APP_STORAGE_KEY = 'nexus_ai_state';

export const CATEGORIES = [
  'LLM Architectures',
  'Multimodal Models',
  'Robotics',
  'AI Policy & Ethics',
  'Compute & Infrastructure',
  'Open Source Releases',
  'Enterprise AI',
  'Agentic Frameworks'
];

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { TechnicalProfile, DigestItem, GroundingSource } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async generateDigest(profile: TechnicalProfile, previousTitles: string[] = []): Promise<DigestItem> {
    const prompt = `
      Act as a high-level Intelligence Analyst specializing in AI. 
      Generate a high-density, source-verified "Knowledge Digest" for the last 24 hours of AI developments.

      User Technical Profile: ${profile.depth}
      Key Focus Areas: ${profile.focusAreas.join(', ')}

      CRITICAL INSTRUCTIONS:
      1. Use Google Search to find the most recent and relevant breakthroughs.
      2. DEDUPLICATION: Do not include news already covered in these previous titles: ${previousTitles.join(', ')}.
      3. ANALYSIS: For a ${profile.depth}, provide deep technical context rather than marketing hype.
      4. FORMAT: Return the response as a structured report. 
         - A title for the day's main movement.
         - A dense summary.
         - 3-5 high-impact takeaways.
         - A technical "Deep Dive" section explaining the 'how' behind the breakthroughs.
         - An Impact Score from 1-10.
    `;

    try {
      const response: GenerateContentResponse = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          tools: [{ googleSearch: {} }],
          temperature: 0.7,
        },
      });

      const text = response.text || "Failed to generate summary.";

      // Extract grounding sources
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const sources: GroundingSource[] = groundingChunks
        .filter((chunk: any) => chunk.web)
        .map((chunk: any) => ({
          title: chunk.web.title || 'Source',
          uri: chunk.web.uri,
        }));

      // Parse key takeaways and technical analysis from response
      // In a real production app, we would use structured JSON output via responseSchema.
      // For this implementation, we simulate extraction or use a robust prompt.

      return {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        title: this.extractSection(text, 'Title') || "Daily AI Intelligence Report",
        summary: this.extractSection(text, 'Summary') || text.substring(0, 300) + "...",
        keyTakeaways: this.extractList(text, 'Takeaways'),
        technicalAnalysis: this.extractSection(text, 'Deep Dive') || "Detailed analysis not available.",
        sources,
        impactScore: parseInt(this.extractSection(text, 'Impact Score') || "7"),
      };
    } catch (error) {
      console.error("Gemini Pipeline Error:", error);
      throw error;
    }
  }

  private extractSection(text: string, sectionName: string): string | null {
    const regex = new RegExp(`${sectionName}:?\\s*([\\s\\S]*?)(?=\\n\\n|\\n[A-Z]|$)`, 'i');
    const match = text.match(regex);
    return match ? match[1].trim() : null;
  }

  private extractList(text: string, sectionName: string): string[] {
    const section = this.extractSection(text, sectionName);
    if (!section) return [];
    return section
      .split('\n')
      .map(line => line.replace(/^[-*•\d.]+\s*/, '').trim())
      .filter(line => line.length > 0);
  }
}

import React from 'react';
import { TechnicalDepth, TechnicalProfile } from '../types';
import { CATEGORIES } from '../constants';

interface SidebarProps {
  profile: TechnicalProfile;
  setProfile: (p: TechnicalProfile) => void;
  onRefresh: () => void;
  isProcessing: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ profile, setProfile, onRefresh, isProcessing }) => {
  const toggleArea = (area: string) => {
    const newAreas = profile.focusAreas.includes(area)
      ? profile.focusAreas.filter(a => a !== area)
      : [...profile.focusAreas, area];
    setProfile({ ...profile, focusAreas: newAreas });
  };

  return (
    <div className="w-80 h-full border-r border-zinc-800 bg-zinc-950 flex flex-col p-6 space-y-8 overflow-y-auto shrink-0">
      <div className="flex items-center space-x-3 mb-4">
        <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
          <i className="fas fa-bolt text-white"></i>
        </div>
        <h1 className="text-xl font-bold tracking-tight">NEXUS AI</h1>
      </div>

      <section className="space-y-4">
        <h2 className="text-xs font-semibold text-zinc-500 uppercase tracking-widest">Technical Depth</h2>
        <div className="grid grid-cols-1 gap-2">
          {Object.values(TechnicalDepth).map((depth) => (
            <button
              key={depth}
              onClick={() => setProfile({ ...profile, depth })}
              className={`text-sm px-4 py-2.5 rounded-lg text-left transition-all duration-200 border ${
                profile.depth === depth 
                  ? 'bg-indigo-600/10 border-indigo-500 text-indigo-400' 
                  : 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:border-zinc-700'
              }`}
            >
              {depth}
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-xs font-semibold text-zinc-500 uppercase tracking-widest">Focus Vectors</h2>
        <div className="flex flex-wrap gap-2">
          {CATEGORIES.map((area) => (
            <button
              key={area}
              onClick={() => toggleArea(area)}
              className={`text-xs px-3 py-1.5 rounded-full border transition-all ${
                profile.focusAreas.includes(area)
                  ? 'bg-zinc-100 text-zinc-900 border-zinc-100'
                  : 'bg-zinc-900 text-zinc-400 border-zinc-800 hover:border-zinc-700'
              }`}
            >
              {area}
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-xs font-semibold text-zinc-500 uppercase tracking-widest">Schedule</h2>
        <select 
          value={profile.digestInterval}
          onChange={(e) => setProfile({...profile, digestInterval: e.target.value as any})}
          className="w-full bg-zinc-900 border border-zinc-800 text-sm rounded-lg p-2.5 outline-none focus:border-indigo-500"
        >
          <option value="4h">Every 4 Hours</option>
          <option value="12h">Every 12 Hours</option>
          <option value="24h">Daily (24h)</option>
        </select>
      </section>

      <div className="pt-6 mt-auto border-t border-zinc-800">
        <button
          onClick={onRefresh}
          disabled={isProcessing}
          className={`w-full flex items-center justify-center space-x-2 py-3 rounded-lg font-medium transition-all ${
            isProcessing 
              ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' 
              : 'bg-white text-black hover:bg-zinc-200'
          }`}
        >
          {isProcessing ? (
            <i className="fas fa-circle-notch fa-spin"></i>
          ) : (
            <i className="fas fa-sync"></i>
          )}
          <span>{isProcessing ? 'Synthesizing...' : 'Run Pipeline'}</span>
        </button>
        <p className="text-[10px] text-center text-zinc-600 mt-4 leading-relaxed">
          Powered by Gemini 3 Pro & Google Search Grounding.
          Deduplication active.
        </p>
      </div>
    </div>
  );
};

export default Sidebar;

